import React, { useEffect, useState, useMemo, useCallback, useRef } from 'react';
import {
  Heart,
  ThumbsUp,
  ThumbsDown,
  Sliders,
  X,
  ChevronRight,
  Gift,
  Loader2,
  Package,
  ShoppingCart,
  Tag,
  Menu
} from 'lucide-react';

// Debounce-Funktion
const debounce = (func, wait) => {
  let timeout;
  return (...args) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
};

// Alert-Komponente
const Alert = React.memo(({ variant = 'error', children }) => {
  const styles = useMemo(
    () => ({
      bgColor: variant === 'error' ? 'bg-red-100' : 'bg-green-100',
      textColor: variant === 'error' ? 'text-red-900' : 'text-green-900'
    }),
    [variant]
  );
  return (
    <div className={`${styles.bgColor} ${styles.textColor} p-4 rounded-lg border border-current/20 shadow-sm my-6 animate-fade-in min-h-[80px] flex items-center justify-center`}>
      {children}
    </div>
  );
});

// Produktkarten-Komponente
const ProductCard = React.memo(({ product, onLike, onDislike, likedProducts = [] }) => {
  const imageUrl = useMemo(() => {
    if (!product.image) return '/placeholder-gift.jpg';
    if (typeof product.image === 'string') {
      if (product.image.includes('src=')) {
        const match = product.image.match(/src="([^"]+)"/);
        return match ? match[1] : '/placeholder-gift.jpg';
      }
      if (product.image.startsWith('http')) return product.image;
      return product.image;
    }
    return '/placeholder-gift.jpg';
  }, [product.image]);

  const handleImageError = useCallback((e) => {
    e.currentTarget.src = '/placeholder-gift.jpg';
  }, []);

  return (
    <div className="bg-white rounded-2xl shadow-md overflow-hidden group transform transition-all duration-300 hover:shadow-xl hover:-translate-y-2 border border-pink-100">
      <div className="relative aspect-[4/3] bg-pink-50">
        <a href={product.url} className="block focus:outline-none">
          <img
            src={imageUrl}
            alt={product.name}
            width={400}
            height={300}
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
            onError={handleImageError}
          />
          <div className="absolute inset-0 bg-gradient-to-t from-gray-900/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        </a>
        {onLike && (
          <button
            className="absolute top-3 right-3 p-2 bg-white/90 rounded-full shadow-sm group-hover:opacity-100 opacity-0 transition-all duration-300 hover:bg-pink-100 focus:outline-none"
            onClick={() => onLike(product.id)}
          >
            <Heart className={`w-5 h-5 ${likedProducts.includes(product.id) ? 'text-pink-500 fill-pink-500' : 'text-pink-500'}`} />
          </button>
        )}
      </div>
      <div className="p-4 flex flex-col flex-grow">
        <h3 className="text-lg font-semibold mb-2 text-gray-800 line-clamp-2">{product.name}</h3>
        <div className="flex justify-between items-center gap-4 mt-auto">
          <a
            href={product.url}
            className="text-purple-500 hover:text-purple-600 font-medium transition-colors duration-200 flex items-center"
          >
            Details
            <ChevronRight className="w-4 h-4 ml-1" />
          </a>
          <a
            href={`/redirect.php?product=${product.slug}`}
            className="px-4 py-2 bg-pink-500 text-white rounded-full hover:bg-pink-600 transition-all duration-300 font-medium flex items-center shadow-md"
          >
            Zum Shop
            <ChevronRight className="w-4 h-4 ml-2" />
          </a>
        </div>
      </div>
    </div>
  );
});

