// Produkt-Raster-Komponente
const ProductGrid = React.memo(
  ({ products, loading, error, onLike, onDislike, likedProducts, loadMore, hasMore, showMore, setShowMore }) => {
    const observer = useRef();
    const lastProductRef = useCallback(
      (node) => {
        if (loading || !hasMore) return;
        if (observer.current) observer.current.disconnect();
        observer.current = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) loadMore();
          },
          { rootMargin: '100px' }
        );
        if (node) observer.current.observe(node);
      },
      [loading, hasMore, loadMore]
    );

    if (loading && !products.length) {
      return (
        <div className="flex flex-col items-center py-16">
          <Loader2 className="w-10 h-10 text-pink-500 animate-spin" />
          <span className="mt-4 text-gray-700 text-lg font-medium">Geschenke werden geladen…</span>
        </div>
      );
    }
    if (error) return <Alert>{error}</Alert>;
    if (!products.length)
      return (
        <div className="text-center py-16">
          <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <p className="text-gray-600 text-lg font-medium">Keine Geschenke gefunden</p>
        </div>
      );

    const initialProducts = products.slice(0, 8);

    return (
      <div className="flex flex-col items-center">
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-6 w-full">
          {(showMore ? products : initialProducts).map((p, index) => (
            <div
              key={p.id}
              ref={index === (showMore ? products.length : initialProducts.length) - 1 ? lastProductRef : null}
            >
              <ProductCard
                product={p}
                onLike={onLike}
                onDislike={onDislike}
                likedProducts={likedProducts}
              />
            </div>
          ))}
        </div>
        {!showMore && products.length > 8 && (
          <button
            onClick={() => setShowMore(true)}
            className="mt-8 px-6 py-3 bg-purple-500 text-white rounded-full hover:bg-purple-600 transition-all duration-300 font-medium shadow-md"
          >
            Mehr Geschenke
          </button>
        )}
        {loading && showMore && <Loader2 className="w-8 h-8 text-pink-500 animate-spin mt-8" />}
      </div>
    );
  }
);

